import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Durability- How Safe Is My Data? - Dan van der Ster, CLYSO","description":"","frontmatter":{"title":"Ceph Durability- How Safe Is My Data? - Dan van der Ster, CLYSO","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","数据持久性","分布式存储","CRUSH算法","可用性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Durability_-_How_Safe_Is_My_Data_-_Dan_van_der_Ster_CLYSO.md","filePath":"posts/2025/Ceph_Durability_-_How_Safe_Is_My_Data_-_Dan_van_der_Ster_CLYSO.md","lastUpdated":1780459816000}'),i={name:"posts/2025/Ceph_Durability_-_How_Safe_Is_My_Data_-_Dan_van_der_Ster_CLYSO.md"};function o(n,a,s,_,h,p){return t(),l("div",null,[...a[0]||(a[0]=[r('<h3 id="ceph-数据持久性评估会议纪要" tabindex="-1"><strong>Ceph 数据持久性评估会议纪要</strong> <a class="header-anchor" href="#ceph-数据持久性评估会议纪要" aria-label="Permalink to &quot;**Ceph 数据持久性评估会议纪要**&quot;">​</a></h3><h4 id="会议主题" tabindex="-1"><strong>会议主题</strong> <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;**会议主题**&quot;">​</a></h4><p>Ceph 数据持久性（Durability）评估：如何确保数据安全？</p><h4 id="主讲人" tabindex="-1"><strong>主讲人</strong> <a class="header-anchor" href="#主讲人" aria-label="Permalink to &quot;**主讲人**&quot;">​</a></h4><p>Dan（CLYO 成员，Ceph 执行委员会）</p><h4 id="会议主要内容" tabindex="-1"><strong>会议主要内容</strong> <a class="header-anchor" href="#会议主要内容" aria-label="Permalink to &quot;**会议主要内容**&quot;">​</a></h4><ol><li><p><strong>背景与动机</strong></p><ul><li>随着存储设备容量快速增长，Ceph 社区提出增加 PG（Placement Group）数量以应对更大容量的 OSD（Object Storage Daemon）。</li><li>但增加 PG 可能影响 Ceph 的数据持久性和可用性，需量化评估。</li></ul></li><li><p><strong>核心概念澄清</strong></p><ul><li><strong>Durability</strong>：数据丢失概率，如 Amazon S3 的“11 个 9”表示每年每 100TB 丢失 1KB 数据。</li><li><strong>Availability</strong>：服务宕机时间，如“4 个 9”表示每年约 53 分钟不可用。</li><li>Ceph 通过 CRUSH 算法、PG 分布和副本/纠删码实现数据保护。</li></ul></li><li><p><strong>数据持久性模拟工具</strong></p><ul><li>Dan 开发了一个可靠性计算器，采用蒙特卡洛模拟评估不同配置下的数据丢失风险。</li><li>支持两种模式：Simulate（模拟不同集群配置）和 Analyze（分析当前配置的风险）。</li></ul></li><li><p><strong>关键发现</strong></p><ul><li><strong>PG 数量影响</strong>：增加 PG 数量会降低 MTTDL（平均数据丢失时间），但耐久性仍高。</li><li><strong>纠删码 vs. 副本</strong>：K+M=4+2 纠删码耐久性低于 3 副本。</li><li><strong>对象大小与恢复速度</strong>：小对象集群的 MTTDL 较低，但恢复速度慢。</li><li><strong>集群规模悖论</strong>：大规模集群的 MTTDL 反而低于小集群，需进一步验证。</li></ul></li><li><p><strong>优化建议</strong></p><ul><li>避免纠删码 K+M=4+2，优先选择 4+3 或更高冗余。</li><li>监控 PG 恢复时间，设定告警阈值。</li><li>谨慎调整 <code>osd_recovery_sleep</code>。</li></ul></li></ol><h4 id="行动计划" tabindex="-1"><strong>行动计划</strong> <a class="header-anchor" href="#行动计划" aria-label="Permalink to &quot;**行动计划**&quot;">​</a></h4><ol><li>邀请社区审查计算器的数学模型。</li><li>逐步提高 <code>target_pg_per_osd</code> 至 200-300。</li><li>文档化小对象集群的风险及优化方案。</li><li>研究大规模集群的耐久性异常原因。</li></ol><h4 id="q-a-摘要" tabindex="-1"><strong>Q&amp;A 摘要</strong> <a class="header-anchor" href="#q-a-摘要" aria-label="Permalink to &quot;**Q&amp;A 摘要**&quot;">​</a></h4><ul><li>MClock 影响：需结合实际负载评估小对象恢复速度。</li><li>集群规模疑问：可能涉及“生日问题”或 CRUSH 分布特性，需进一步研究。</li><li>文档更新：补充对象大小、纠删码策略等关键因素。</li></ul><h4 id="工具获取" tabindex="-1"><strong>工具获取</strong> <a class="header-anchor" href="#工具获取" aria-label="Permalink to &quot;**工具获取**&quot;">​</a></h4><ul><li>代码仓库：<code>ceph/ceph</code> PR</li><li>其他工具：<code>clio.com/tools</code> 提供集群配置对比、最佳实践检查等功能。</li></ul><h4 id="会议总结" tabindex="-1"><strong>会议总结</strong> <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;**会议总结**&quot;">​</a></h4><p>本次会议重点讨论了 Ceph 数据持久性的评估方法，通过模拟工具分析了不同配置下的数据丢失风险，并提出了优化建议。会议强调了监控 PG 恢复时间、谨慎调整配置的重要性，并计划进一步研究大规模集群的耐久性问题。</p>',15)])])}const u=e(i,[["render",o]]);export{c as __pageData,u as default};
